import torch


def run(x, p, train):
    return torch.alpha_dropout(x, p, train)


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    ref = ref_outputs[0]
    sol = sol_outputs[0]
    if tuple(ref.shape) != tuple(sol.shape):
        return {"passed": False, "message": f"shape {tuple(sol.shape)} vs {tuple(ref.shape)}"}
    if ref.dtype != sol.dtype:
        return {"passed": False, "message": f"dtype {sol.dtype} vs {ref.dtype}"}
    train = inputs[2]
    if not train:
        r = ref.detach().to("cpu")
        s = sol.detach().to("cpu")
        if not torch.equal(r, s):
            return {"passed": False, "message": "eval mode expected identity"}
    return {"passed": True, "message": "", "metrics": {}}
